<?php
require_once __DIR__.'/../../includes/init.php'; require_role('admin'); require_once __DIR__.'/../../includes/layout.php';$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=(string)($_POST['action']??'');try{
 if(in_array($act,['add','update'],true)){$id=(int)($_POST['id_kendaraan']??0);$plate=strtoupper(trim((string)($_POST['plat_nomor']??'')));$type=(string)($_POST['jenis_kendaraan']??'');$color=trim((string)($_POST['warna']??''));$owner=trim((string)($_POST['pemilik']??''));if(!preg_match('/^[A-Z0-9 ]{2,15}$/',$plate))throw new InvalidArgumentException('Format plat nomor tidak valid.');if(!in_array($type,['motor','mobil','lainnya'],true)||$color===''||mb_strlen($color)>20||$owner===''||mb_strlen($owner)>100)throw new InvalidArgumentException('Lengkapi jenis, warna, dan pemilik dengan benar.');if($act==='add'){$s=$pdo->prepare('INSERT INTO tb_kendaraan(plat_nomor,jenis_kendaraan,warna,pemilik,id_user) VALUES(?,?,?,?,?)');$s->execute([$plate,$type,$color,$owner,current_user()['id']]);log_activity('Menambah kendaraan '.$plate);}else{$s=$pdo->prepare('UPDATE tb_kendaraan SET plat_nomor=?,jenis_kendaraan=?,warna=?,pemilik=? WHERE id_kendaraan=?');$s->execute([$plate,$type,$color,$owner,$id]);log_activity('Mengubah data kendaraan '.$plate);}flash('success','Data kendaraan berhasil disimpan.');redirect('admin/kendaraan/index.php');}
 if($act==='delete'){$id=input_int('id_kendaraan');$s=$pdo->prepare('SELECT COUNT(*) FROM tb_transaksi WHERE id_kendaraan=?');$s->execute([$id]);if((int)$s->fetchColumn()>0)throw new InvalidArgumentException('Kendaraan memiliki riwayat transaksi sehingga tidak dapat dihapus.');$pdo->prepare('DELETE FROM tb_kendaraan WHERE id_kendaraan=?')->execute([$id]);log_activity('Menghapus kendaraan ID '.$id);flash('success','Kendaraan berhasil dihapus.');redirect('admin/kendaraan/index.php');}throw new InvalidArgumentException('Aksi tidak valid.');
}catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():(($e instanceof PDOException&&$e->getCode()==='23000')?'Plat nomor sudah terdaftar.':'Operasi kendaraan gagal.');if(!($e instanceof InvalidArgumentException)&&!($e instanceof PDOException&&$e->getCode()==='23000'))error_log('[ParkirSTRD kendaraan] '.$e->getMessage());}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM tb_kendaraan WHERE id_kendaraan=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}$q=trim((string)($_GET['q']??''));$type=(string)($_GET['jenis']??'');$page=page_number();$lim=10;$where=[];$p=[];if($q!==''){$where[]='(k.plat_nomor LIKE ? OR k.pemilik LIKE ?)';$p[]='%'.$q.'%';$p[]='%'.$q.'%';}if(in_array($type,['motor','mobil','lainnya'],true)){$where[]='k.jenis_kendaraan=?';$p[]=$type;}$ws=$where?' WHERE '.implode(' AND ',$where):'';$c=$pdo->prepare('SELECT COUNT(*) FROM tb_kendaraan k'.$ws);$c->execute($p);$total=(int)$c->fetchColumn();$s=$pdo->prepare("SELECT k.*,EXISTS(SELECT 1 FROM tb_transaksi t WHERE t.id_kendaraan=k.id_kendaraan AND t.status='masuk') AS sedang_parkir FROM tb_kendaraan k$ws ORDER BY k.id_kendaraan DESC LIMIT $lim OFFSET ".(($page-1)*$lim));$s->execute($p);$rows=$s->fetchAll();render_header('Manajemen Kendaraan','kendaraan');?>
<div class="page-intro"><div><h2>Data kendaraan</h2><p>Daftarkan plat nomor agar dapat dipilih saat transaksi parkir.</p></div></div><?php if($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><section class="panel"><div class="panel-heading"><div><h2><?= $edit?'Edit kendaraan':'Tambah kendaraan' ?></h2><p>Plat nomor harus unik. Kendaraan dengan transaksi tidak dapat dihapus.</p></div></div><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $edit?'update':'add' ?>"><?php if($edit): ?><input type="hidden" name="id_kendaraan" value="<?= (int)$edit['id_kendaraan'] ?>"><?php endif; ?><div class="field"><label>Plat nomor</label><input name="plat_nomor" required maxlength="15" placeholder="M 1234 AB" value="<?= h($edit['plat_nomor']??'') ?>"></div><div class="field"><label>Jenis kendaraan</label><select name="jenis_kendaraan" required><?php foreach(['motor'=>'Motor','mobil'=>'Mobil','lainnya'=>'Lainnya'] as $k=>$v): ?><option value="<?= $k ?>" <?= ($edit['jenis_kendaraan']??'motor')===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></div><div class="field"><label>Warna</label><input name="warna" maxlength="20" required value="<?= h($edit['warna']??'') ?>"></div><div class="field"><label>Nama pemilik</label><input name="pemilik" maxlength="100" required value="<?= h($edit['pemilik']??'') ?>"></div><div class="form-actions"><?php if($edit): ?><a class="btn btn-secondary" href="<?= h(url('admin/kendaraan/index.php')) ?>">Batal</a><?php endif; ?><button class="btn btn-primary"><?= $edit?'Simpan perubahan':'Tambah kendaraan' ?></button></div></form></section>
<section class="panel"><div class="table-toolbar"><div><strong>Daftar kendaraan</strong><div class="muted" style="margin-top:4px"><?= $total ?> kendaraan</div></div><form method="get" class="toolbar-right"><div class="search-box"><input name="q" placeholder="Plat nomor / pemilik" value="<?= h($q) ?>"></div><select class="filter-control" name="jenis" data-auto-submit><option value="">Semua jenis</option><?php foreach(['motor','mobil','lainnya'] as $t): ?><option value="<?= $t ?>" <?= $type===$t?'selected':'' ?>><?= ucfirst($t) ?></option><?php endforeach; ?></select><button class="btn btn-secondary">Cari</button></form></div><div class="table-wrap"><table><thead><tr><th>Plat Nomor</th><th>Jenis</th><th>Warna</th><th>Pemilik</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td class="td-main"><?= h($r['plat_nomor']) ?></td><td><?= h(ucfirst($r['jenis_kendaraan'])) ?></td><td><?= h($r['warna']) ?></td><td><?= h($r['pemilik']) ?></td><td><?= $r['sedang_parkir']?status_badge('masuk'):status_badge('keluar') ?></td><td><div class="table-actions"><a class="btn btn-secondary btn-sm" href="<?= h(url('admin/kendaraan/index.php?edit='.(int)$r['id_kendaraan'])) ?>">Edit</a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id_kendaraan" value="<?= (int)$r['id_kendaraan'] ?>"><button class="btn btn-danger btn-sm" data-confirm="Hapus data kendaraan ini? Riwayat transaksi harus kosong.">Hapus</button></form></div></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="6"><div class="empty-state">Data kendaraan tidak ditemukan.</div></td></tr><?php endif; ?></tbody></table></div><div class="table-foot"><span>Menampilkan <?= count($rows) ?> dari <?= $total ?> kendaraan</span><?= pagination($total,$lim,$page,url('admin/kendaraan/index.php?q='.rawurlencode($q).'&jenis='.rawurlencode($type))) ?></div></section><?php render_footer(); ?>